// Native JS utilities to replace lodash
function sortBy<T>(arr: T[], key: keyof T): T[] {
  return [...arr].sort((a, b) => {
    const aVal = a[key];
    const bVal = b[key];
    if (typeof aVal === 'number' && typeof bVal === 'number') {
      return aVal - bVal;
    }
    return String(aVal).localeCompare(String(bVal));
  });
}

function meanBy<T>(arr: T[], key: keyof T): number {
  if (arr.length === 0) return 0;
  const sum = arr.reduce((acc, item) => {
    const val = item[key];
    return acc + (typeof val === 'number' ? val : 0);
  }, 0);
  return sum / arr.length;
}

function sumBy<T>(arr: T[], key: keyof T): number {
  return arr.reduce((acc, item) => {
    const val = item[key];
    return acc + (typeof val === 'number' ? val : 0);
  }, 0);
}

function maxBy<T>(arr: T[], key: keyof T): T | undefined {
  if (arr.length === 0) return undefined;
  return arr.reduce((max, item) => {
    const itemVal = item[key];
    const maxVal = max[key];
    if (typeof itemVal === 'number' && typeof maxVal === 'number') {
      return itemVal > maxVal ? item : max;
    }
    return item;
  });
}

function minBy<T>(arr: T[], key: keyof T): T | undefined {
  if (arr.length === 0) return undefined;
  return arr.reduce((min, item) => {
    const itemVal = item[key];
    const minVal = min[key];
    if (typeof itemVal === 'number' && typeof minVal === 'number') {
      return itemVal < minVal ? item : min;
    }
    return item;
  });
}

// Native JS utilities to replace mathjs
function mean(arr: number[]): number {
  if (arr.length === 0) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function median(arr: number[]): number {
  if (arr.length === 0) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function std(arr: number[]): number {
  if (arr.length === 0) return 0;
  const m = mean(arr);
  const variance = arr.reduce((acc, val) => acc + Math.pow(val - m, 2), 0) / arr.length;
  return Math.sqrt(variance);
}

function variance(arr: number[]): number {
  if (arr.length === 0) return 0;
  const m = mean(arr);
  return arr.reduce((acc, val) => acc + Math.pow(val - m, 2), 0) / arr.length;
}

function quantileSeq(arr: number[], q: number): number {
  if (arr.length === 0) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  const index = q * (sorted.length - 1);
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  const weight = index % 1;

  if (lower === upper) {
    return sorted[lower];
  }
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
}

